<?php
/**
 * Offer builder (GAS-CP-R33-001): an offer assembled in the portal from the rate cards — lines (quantity × unit price,
 * local / overseas zone, discount), text blocks (introduction, scope, exclusions, validity, payment, terms, closing)
 * copied from the templates kept in Settings › Offer texts and edited on the offer, and the offer document (PDF + Word)
 * generated by the portal with the branch's logo and legal lines. Issue archives the revision (R0, R1 …), sets the
 * document on the offer and marks a draft offer as sent. Who may build offers: Golden A/S roles with "May prepare
 * offers" (and financial data visible); administrators always.
 */

const OB_LAYOUTS = ['service', 'system', 'remote'];
const OB_BLOCK_KEYS = ['intro', 'scope', 'exclusions', 'validity', 'payment', 'terms', 'closing'];   // 'lines' sits between scope and exclusions
const OB_PLACEHOLDERS = ['no', 'title', 'vessel', 'customer', 'project', 'ticket', 'validity_days', 'valid_until', 'user', 'branch', 'date', 'currency', 'rate_list'];

function ob_has(): bool {
    static $h = null;
    if ($h === null) { try { $h = (bool) db()->query("SHOW TABLES LIKE 'offer_lines'")->fetch() && (bool) db()->query("SHOW COLUMNS FROM offers LIKE 'layout'")->fetch(); } catch (Throwable $e) { $h = false; } }
    return $h;
}
/** May the signed-in person prepare offers (lines, texts, issue)? */
function ob_can(): bool {
    static $v = null;
    if ($v !== null) return $v;
    if (!is_staff() || !of_visible() || !ob_has()) return $v = false;
    if (is_cp_admin()) return $v = true;
    $u = current_user();
    try {
        if (!(bool) db()->query("SHOW COLUMNS FROM staff_roles LIKE 'can_offer'")->fetch() || empty($u['staff_role_id'])) return $v = true;
        $f = scalar('SELECT can_offer FROM staff_roles WHERE id = ?', [(int)$u['staff_role_id']]);
        return $v = ($f === null || (int)$f === 1);
    } catch (Throwable $e) { return $v = true; }
}
function ob_layout_label(string $l): string { return t('ob.l_' . $l); }
function ob_block_label(string $k): string { return t('ob.b_' . $k); }

/* ---------------------------------------------------------------- the "general" project of a vessel (offers without a project) */
/** The vessel's general project (created on first use: "General — <vessel>", code GEN-<id>), so a vessel-level offer has a home for its documents. */
function ob_general_project(int $vesselId): int {
    $v = one('SELECT * FROM vessels WHERE id = ?', [$vesselId]); if (!$v) throw new RuntimeException(t('err.notfound'));
    $code = 'GEN-' . $vesselId;
    $pid = (int) scalar('SELECT id FROM projects WHERE vessel_id = ? AND project_code = ? LIMIT 1', [$vesselId, $code]);
    if ($pid) return $pid;
    $u = current_user();
    q("INSERT INTO projects (customer_id, vessel_id, name, project_code, source, status, category, project_manager, pm_user_id) VALUES (?,?,?,?,'manual','active',?,?,?)",
      [(int)$v['customer_id'], $vesselId, t('ob.general_project', ['v' => $v['name']]), $code, t('ob.general_cat'), (string)($u['full_name'] ?? ''), (int)($u['id'] ?? 0) ?: null]);
    return (int) db()->lastInsertId();
}

/** Portal offer number for offers without an ERP series: <branch prefix>-OF-<year>-<nnn>. */
function ob_offer_no(int $pid, ?int $sid = null): string {
    $pre = function_exists('br_prefix') ? br_prefix($pid, $sid) : 'GAS'; $base = $pre . '-OF-' . date('Y') . '-';
    $n = (int) scalar("SELECT MAX(CAST(SUBSTRING(offer_no, ?) AS UNSIGNED)) FROM offers WHERE offer_no LIKE ?", [strlen($base) + 1, $base . '%']) + 1;
    return $base . sprintf('%03d', $n);
}

/* ---------------------------------------------------------------- text templates (Settings › Offer texts) */
function ot_all(): array {
    if (!ob_has()) return [];
    return all('SELECT t.*, b.code AS branch_code, c.name AS customer_name, u.full_name AS updated_name FROM offer_texts t LEFT JOIN branches b ON b.id = t.branch_id LEFT JOIN customers c ON c.id = t.customer_id LEFT JOIN customer_users u ON u.id = t.updated_by ORDER BY FIELD(t.block_key, ' . implode(',', array_map(fn($k) => "'$k'", OB_BLOCK_KEYS)) . '), t.customer_id IS NULL, t.branch_id IS NULL, t.layout, t.locale, t.name');
}
function ot_get(int $id): ?array { return ob_has() ? one('SELECT * FROM offer_texts WHERE id = ?', [$id]) : null; }
function ot_builtin(string $key, string $layout, string $locale): array {
    $body = t_in('ob.d_' . $key . '_' . $layout, $locale); if ($body === 'ob.d_' . $key . '_' . $layout) $body = t_in('ob.d_' . $key, $locale);
    return ['title' => t_in('ob.b_' . $key, $locale), 'body' => $body === 'ob.d_' . $key ? '' : $body];
}
function ot_resolve(string $key, string $layout, string $locale, ?int $bid, ?int $cid): ?array {
    if (!ob_has()) return null;
    $best = null; $bs = -1;
    foreach (all('SELECT * FROM offer_texts WHERE block_key = ? AND is_active = 1', [$key]) as $t) {
        $s = 0;
        if ($t['customer_id'] !== null) { if ((int)$t['customer_id'] !== (int)$cid) continue; $s += 8; }
        if ($t['branch_id'] !== null)   { if ((int)$t['branch_id'] !== (int)$bid) continue; $s += 4; }
        if ($t['locale'] !== '')        { if ($t['locale'] !== $locale) continue; $s += 2; }
        if ($t['layout'] !== '')        { if ($t['layout'] !== $layout) continue; $s += 1; }
        if ($s > $bs) { $bs = $s; $best = $t; }
    }
    return $best;
}
function ot_save_from_post(): int {
    require_cp_admin(); if (!ob_has()) throw new RuntimeException(t('ob.need_db'));
    $u = current_user(); $id = (int)($_POST['id'] ?? 0);
    $key = in_array($_POST['block_key'] ?? '', OB_BLOCK_KEYS, true) ? $_POST['block_key'] : 'intro';
    $layout = in_array($_POST['layout'] ?? '', OB_LAYOUTS, true) ? $_POST['layout'] : '';
    $locale = isset(LOCALES[(string)($_POST['locale'] ?? '')]) ? (string)$_POST['locale'] : '';
    $bid = (int)($_POST['branch_id'] ?? 0) ?: null; $cid = (int)($_POST['customer_id'] ?? 0) ?: null;
    $name = mb_substr(trim((string)($_POST['name'] ?? '')), 0, 120) ?: ob_block_label($key);
    $title = mb_substr(trim((string)($_POST['title'] ?? '')), 0, 120); $body = mb_substr(str_replace("\r\n", "\n", (string)($_POST['body'] ?? '')), 0, 20000);
    if (trim($body) === '') throw new RuntimeException(t('et.need_body'));
    $active = !empty($_POST['is_active']) ? 1 : 0;
    if ($id) q('UPDATE offer_texts SET block_key=?, layout=?, locale=?, branch_id=?, customer_id=?, name=?, title=?, body=?, is_active=?, updated_by=? WHERE id=?', [$key, $layout, $locale, $bid, $cid, $name, $title, $body, $active, (int)$u['id'], $id]);
    else { q('INSERT INTO offer_texts (block_key, layout, locale, branch_id, customer_id, name, title, body, is_active, updated_by) VALUES (?,?,?,?,?,?,?,?,?,?)', [$key, $layout, $locale, $bid, $cid, $name, $title, $body, $active, (int)$u['id']]); $id = (int) db()->lastInsertId(); }
    return $id;
}
function ot_delete(int $id): void { require_cp_admin(); if (ob_has()) q('DELETE FROM offer_texts WHERE id = ?', [$id]); }
function ot_duplicate(int $id): int {
    require_cp_admin(); $t = ot_get($id); if (!$t) throw new RuntimeException(t('err.notfound'));
    q('INSERT INTO offer_texts (block_key, layout, locale, branch_id, customer_id, name, title, body, is_active, updated_by) VALUES (?,?,?,?,?,?,?,?,0,?)', [$t['block_key'], $t['layout'], $t['locale'], $t['branch_id'], $t['customer_id'], mb_substr($t['name'] . ' (2)', 0, 120), $t['title'], $t['body'], (int)current_user()['id']]);
    return (int) db()->lastInsertId();
}

/* ---------------------------------------------------------------- placeholders */
function ob_vars(array $o): array {
    $u = current_user(); $b = function_exists('br_of') ? br_of((int)$o['project_id'], $o['subproject_id'] ? (int)$o['subproject_id'] : null) : [];
    $rl = !empty($o['rate_list_id']) ? rl_get((int)$o['rate_list_id']) : null;
    $valid = $o['valid_until'] ?: date('Y-m-d', strtotime(($o['sent_at'] ?: date('Y-m-d')) . ' +' . (int)($o['validity_days'] ?? 30) . ' days'));
    return ['{no}' => $o['offer_no'] . ' ' . $o['revision'], '{title}' => (string)$o['title'], '{vessel}' => (string)($o['vessel'] ?? ''), '{customer}' => (string)($o['customer_name'] ?? ''),
            '{project}' => trim(($o['project_code'] ?? '') . ' ' . ($o['project_name'] ?? '')) . ($o['sub_code'] ?? '' ? ' › ' . $o['sub_code'] : ''), '{ticket}' => (string)($o['ticket_no'] ?? ''),
            '{validity_days}' => (string)(int)($o['validity_days'] ?? 30), '{valid_until}' => fmt_date($valid), '{user}' => (string)($u['full_name'] ?? ''),
            '{branch}' => (string)(($b['trade_name'] ?? '') ?: (($b['legal_name'] ?? '') ?: ($b['name'] ?? 'Golden A/S'))), '{date}' => fmt_date($o['sent_at'] ?: date('Y-m-d')), '{currency}' => (string)$o['currency'],
            '{rate_list}' => $rl ? $rl['doc_ref'] . ' ' . $rl['revision'] : ''];
}
function ob_fill(string $s, array $vars): string { return strtr($s, $vars); }
function ob_locale(array $o): string { return function_exists('et_customer_locale') ? et_customer_locale((int)($o['customer_id'] ?? 0) ?: null) : locale(); }

/* ---------------------------------------------------------------- blocks of one offer */
function ob_blocks(int $offerId): array { return ob_has() ? all('SELECT * FROM offer_blocks WHERE offer_id = ? ORDER BY seq, id', [$offerId]) : []; }
/** Create the blocks from the templates when the offer has none yet (or $force to replace them). */
function ob_blocks_init(array $o, bool $force = false): void {
    if (!ob_has()) return;
    if (!$force && scalar('SELECT COUNT(*) FROM offer_blocks WHERE offer_id = ?', [(int)$o['id']])) return;
    q('DELETE FROM offer_blocks WHERE offer_id = ?', [(int)$o['id']]);
    $loc = ob_locale($o); $b = function_exists('br_of') ? br_of((int)$o['project_id']) : []; $bid = (int)($b['id'] ?? 0) ?: null; $cid = (int)($o['customer_id'] ?? 0) ?: null;
    foreach (OB_BLOCK_KEYS as $i => $k) {
        $t = ot_resolve($k, (string)$o['layout'], $loc, $bid, $cid) ?: ot_builtin($k, (string)$o['layout'], $loc);
        if (trim((string)$t['body']) === '' && !$t) continue;
        q('INSERT INTO offer_blocks (offer_id, block_key, seq, title, body) VALUES (?,?,?,?,?)', [(int)$o['id'], $k, $i * 10, mb_substr((string)($t['title'] ?: ob_block_label($k)), 0, 120), (string)$t['body']]);
    }
}
function ob_block_save(int $offerId, string $key, string $title, string $body): void {
    if (!in_array($key, OB_BLOCK_KEYS, true)) return;
    $title = mb_substr(trim($title), 0, 120); $body = mb_substr(str_replace("\r\n", "\n", $body), 0, 20000);
    if (scalar('SELECT COUNT(*) FROM offer_blocks WHERE offer_id = ? AND block_key = ?', [$offerId, $key])) q('UPDATE offer_blocks SET title = ?, body = ? WHERE offer_id = ? AND block_key = ?', [$title, $body, $offerId, $key]);
    else q('INSERT INTO offer_blocks (offer_id, block_key, seq, title, body) VALUES (?,?,?,?,?)', [$offerId, $key, array_search($key, OB_BLOCK_KEYS, true) * 10, $title, $body]);
}

/* ---------------------------------------------------------------- lines */
function ob_lines(int $offerId): array { return ob_has() ? all('SELECT * FROM offer_lines WHERE offer_id = ? ORDER BY seq, id', [$offerId]) : []; }
function ob_line_total(float $qty, float $price, float $disc): float { return round($qty * $price * (1 - max(0, min(100, $disc)) / 100), 2); }
/** Recompute the totals from the lines (when there are lines) and store them on the offer. */
function ob_recalc(int $offerId): void {
    if (!ob_has()) return;
    $n = (int) scalar('SELECT COUNT(*) FROM offer_lines WHERE offer_id = ? AND kind <> "text"', [$offerId]);
    if (!$n) return;
    $net = (float) scalar('SELECT COALESCE(SUM(line_total), 0) FROM offer_lines WHERE offer_id = ? AND kind <> "text"', [$offerId]);
    $vat = (float) scalar('SELECT vat_pct FROM offers WHERE id = ?', [$offerId]); $vt = round($net * $vat / 100, 2);
    q('UPDATE offers SET amount = ?, vat_total = ?, gross_total = ? WHERE id = ?', [$net, $vt, round($net + $vt, 2), $offerId]);
}
function ob_line_save_from_post(array $o): int {
    if (!ob_can()) throw new RuntimeException(t('err.noaccess'));
    $oid = (int)$o['id']; $id = (int)($_POST['line_id'] ?? 0);
    $kind = in_array($_POST['kind'] ?? '', ['rate', 'free', 'text'], true) ? $_POST['kind'] : 'free';
    $zone = ($_POST['zone'] ?? 'local') === 'overseas' ? 'overseas' : 'local';
    $qty = max(0, (float) str_replace(',', '.', (string)($_POST['qty'] ?? '1'))); $disc = max(0, min(100, (float) str_replace(',', '.', (string)($_POST['discount_pct'] ?? '0'))));
    $price = of_parse_amount((string)($_POST['unit_price'] ?? '0'));
    $desc = mb_substr(trim((string)($_POST['description'] ?? '')), 0, 400); $unit = mb_substr(trim((string)($_POST['unit'] ?? '')), 0, 20); $erp = mb_substr(trim((string)($_POST['erp_code'] ?? '')), 0, 30);
    $notes = mb_substr(trim((string)($_POST['notes'] ?? '')), 0, 255) ?: null; $itemId = null;
    if ($kind === 'rate' && ($rid = (int)($_POST['rate_item_id'] ?? 0))) {
        $it = rl_item($rid); if (!$it) throw new RuntimeException(t('err.notfound'));
        $itemId = $rid; $erp = $erp ?: (string)$it['erp_code']; $desc = $desc ?: (string)$it['description']; $unit = $unit ?: (string)$it['unit'];
        if (empty($_POST['unit_price']) || $price <= 0) $price = (float)(rl_price($it, $zone) ?? 0);
    }
    if ($desc === '') throw new RuntimeException(t('ob.need_desc'));
    if ($kind === 'text') { $qty = 0; $price = 0; $disc = 0; }
    $total = $kind === 'text' ? 0 : ob_line_total($qty, $price, $disc);
    if ($id) q('UPDATE offer_lines SET kind=?, rate_item_id=?, erp_code=?, description=?, unit=?, zone=?, qty=?, unit_price=?, discount_pct=?, line_total=?, notes=? WHERE id=? AND offer_id=?', [$kind, $itemId, $erp, $desc, $unit, $zone, $qty, $price, $disc, $total, $notes, $id, $oid]);
    else { $seq = (int) scalar('SELECT COALESCE(MAX(seq), 0) + 10 FROM offer_lines WHERE offer_id = ?', [$oid]); q('INSERT INTO offer_lines (offer_id, seq, kind, rate_item_id, erp_code, description, unit, zone, qty, unit_price, discount_pct, line_total, notes) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)', [$oid, $seq, $kind, $itemId, $erp, $desc, $unit, $zone, $qty, $price, $disc, $total, $notes]); $id = (int) db()->lastInsertId(); }
    ob_recalc($oid); of_event($oid, 'edited', t('ob.ev_lines'));
    return $id;
}
/** Quick-edit of all lines at once (qty / price / discount per row from the table). */
function ob_lines_bulk_from_post(array $o): void {
    if (!ob_can()) throw new RuntimeException(t('err.noaccess'));
    foreach ((array)($_POST['q'] ?? []) as $lid => $qv) {
        $lid = (int)$lid; $l = one('SELECT * FROM offer_lines WHERE id = ? AND offer_id = ?', [$lid, (int)$o['id']]); if (!$l || $l['kind'] === 'text') continue;
        $qty = max(0, (float) str_replace(',', '.', (string)$qv)); $price = of_parse_amount((string)($_POST['p'][$lid] ?? '0')); $disc = max(0, min(100, (float) str_replace(',', '.', (string)($_POST['d'][$lid] ?? '0'))));
        q('UPDATE offer_lines SET qty = ?, unit_price = ?, discount_pct = ?, line_total = ? WHERE id = ?', [$qty, $price, $disc, ob_line_total($qty, $price, $disc), $lid]);
    }
    if (isset($_POST['vat_pct'])) q('UPDATE offers SET vat_pct = ? WHERE id = ?', [max(0, min(100, (float) str_replace(',', '.', (string)$_POST['vat_pct']))), (int)$o['id']]);
    ob_recalc((int)$o['id']); of_event((int)$o['id'], 'edited', t('ob.ev_lines'));
}
function ob_line_delete(int $offerId, int $lineId): void { if (!ob_can()) throw new RuntimeException(t('err.noaccess')); q('DELETE FROM offer_lines WHERE id = ? AND offer_id = ?', [$lineId, $offerId]); ob_recalc($offerId); }
function ob_line_move(int $offerId, int $lineId, int $dir): void {
    if (!ob_can()) throw new RuntimeException(t('err.noaccess'));
    $ids = array_map('intval', array_column(ob_lines($offerId), 'id')); $i = array_search($lineId, $ids, true); if ($i === false) return;
    $j = $i + ($dir < 0 ? -1 : 1); if ($j < 0 || $j >= count($ids)) return;
    [$ids[$i], $ids[$j]] = [$ids[$j], $ids[$i]];
    foreach ($ids as $k => $id) q('UPDATE offer_lines SET seq = ? WHERE id = ?', [($k + 1) * 10, $id]);
}

/* ---------------------------------------------------------------- document */
function ob_money(float $v, string $cur): string { return number_format($v, 2, ',', '.') . ' ' . $cur; }
function ob_doc_data(array $o): array {
    $o['lines'] = ob_lines((int)$o['id']); ob_blocks_init($o); $o['blocks'] = ob_blocks((int)$o['id']); $o['vars'] = ob_vars($o);
    foreach ($o['blocks'] as &$b) { $b['title'] = ob_fill($b['title'], $o['vars']); $b['body'] = ob_fill($b['body'], $o['vars']); } unset($b);
    return $o;
}
function ob_render_pdf(array $o): string {
    require_once __DIR__ . '/pdf.php';
    $o = ob_doc_data($o); $cur = (string)$o['currency']; $loc = ob_locale($o); $T = fn(string $k, array $v = []) => t_in($k, $loc, $v);
    $pdf = new PdfWriter(); $navy = '#0B1E2D'; $gold = '#C89B3C'; $ink = '#1F2933'; $line = '#C8CED6'; $head = '#EEF2F6';
    $L = 15.0; $R = 195.0; $W = $R - $L; $y = 0.0;
    $bd = function_exists('br_doc') ? br_doc((int)$o['project_id'], $o['subproject_id'] ? (int)$o['subproject_id'] : null) : ['logo' => null, 'name' => 'Golden Automation Systems', 'lines' => [], 'footer' => ''];
    $rev = $o['revision'] . ($o['status'] === 'draft' ? ' · ' . $T('ob.s_draft') : '');
    $header = function () use ($pdf, &$y, $navy, $gold, $L, $R, $o, $bd, $rev, $T) {
        $pdf->addPage(); if (!empty($bd['logo'])) $pdf->image($bd['logo'], 150, 12, 45, 16);
        $pdf->setColor($navy); $pdf->setFont('B', 15); $pdf->text($L, 20, mb_strtoupper($T('ob.doc_title')));
        $pdf->setFont('R', 8.5); $pdf->setColor($gold); $pdf->text($L, 26, $o['offer_no'] . ' · ' . $rev . ' · ' . fmt_date($o['sent_at'] ?: date('Y-m-d')));
        $pdf->setLineWidth(0.6); $pdf->line($L, 30, $R, 30); $y = 36;
    };
    $footer = function () use ($pdf, $L, $R, $o, $bd) { $pdf->setFont('R', 7); $pdf->setColor('#6a7179'); $pdf->text($L, 290, ($bd['footer'] ?: $bd['name']) . ' · ' . $o['offer_no'] . ' ' . $o['revision']); $pdf->text($R, 290, (string)$pdf->pageNo(), 'R'); };
    $need = function (float $hh) use (&$y, $header, $footer) { if ($y + $hh > 276) { $footer(); $header(); } };
    $h1 = function (string $s) use ($pdf, $navy, $gold, $L, $R, &$y, $need) { $y += 3; $need(20); $pdf->setColor($navy); $pdf->setFont('B', 10.5); $pdf->text($L, $y + 4.5, $s); $pdf->setColor($gold); $pdf->setLineWidth(0.4); $pdf->line($L, $y + 6.5, $R, $y + 6.5); $y += 10; };
    $para = function (string $s, float $size = 9) use ($pdf, $ink, $L, $W, &$y, $need) {
        foreach (preg_split('/\n{2,}/', trim($s)) as $p) { $p = trim($p); if ($p === '') continue; $pdf->setFont('R', $size); $need($pdf->paragraphHeight($W, $p, 4.3) + 3); $pdf->setColor($ink); $y += $pdf->paragraph($L, $y, $W, $p, 4.3) + 2.5; }
    };
    $header(); $footer();
    // cover table
    $kv = [[$T('of.no'), $o['offer_no'] . ' · ' . $rev], [$T('of.title_f'), (string)$o['title']], [$T('rp.customer'), (string)($o['customer_name'] ?? '')], [$T('v.one'), (string)($o['vessel'] ?: '—')],
           [$T('pr.one'), $o['vars']['{project}'] ?: '—'], [$T('th.date'), $o['vars']['{date}']], [$T('of.valid_until'), $o['vars']['{valid_until}']], [$T('ob.prepared_by'), $o['vars']['{user}'] . ' · ' . $o['vars']['{branch}']]];
    if (!empty($o['ticket_no'])) $kv[] = [$T('tk.one'), (string)$o['ticket_no']];
    foreach ($kv as [$k, $v]) { $need($pdf->kvHeight($W, 47, $v) + 1); $y += $pdf->kvCell($L, $y, $W, 47, $k, $v, ['labelW' => 44, 'fill' => $head, 'line' => $line, 'navy' => $navy, 'ink' => $ink]); }   // R59-002: wraps
    foreach ($bd['lines'] ?? [] as $i => $ln) { if ($i === 0) $y += 2; $pdf->setFont('R', 7); $pdf->setColor('#6a7179'); $pdf->text($R, $y + 3, $ln, 'R'); $y += 3.2; }
    $y += 4;
    $n = 0; $before = ['intro', 'scope']; $after = ['exclusions', 'validity', 'payment', 'terms', 'closing'];
    $block = function (string $k) use ($o, &$n, $h1, $para) { foreach ($o['blocks'] as $b) if ($b['block_key'] === $k && trim($b['body']) !== '') { $n++; $h1($n . '. ' . $b['title']); $para($b['body']); } };
    foreach ($before as $k) $block($k);
    // lines table
    $n++; $h1($n . '. ' . $T('ob.sec_lines'));
    $cols = [[$T('ob.c_no'), 8, 'C'], [$T('ob.c_code'), 24, 'L'], [$T('ob.c_desc'), 78, 'L'], [$T('ob.c_unit'), 16, 'L'], [$T('ob.c_qty'), 12, 'R'], [$T('ob.c_price'), 20, 'R'], [$T('ob.c_disc'), 10, 'R'], [$T('ob.c_total'), 22, 'R']];
    $cols = function_exists('rc_fit_cols') ? rc_fit_cols($cols, $W) : $cols;
    $hrow = function () use ($pdf, $cols, $navy, $line, $head, $L, &$y) { $pdf->setFont('B', 7.2); $x = $L; $hh = 6; $pdf->setColor($head); $pdf->rect($x, $y, array_sum(array_column($cols, 1)), $hh, 'F'); foreach ($cols as [$lab, $cw, $al]) { $pdf->setColor($line); $pdf->setLineWidth(0.25); $pdf->rect($x, $y, $cw, $hh); $pdf->setColor($navy); $pdf->text($x + 1.5, $y + 4, $lab, $al, $cw - 3); $x += $cw; } $y += $hh; };
    $need(20); $hrow(); $i = 0;
    foreach ($o['lines'] as $ln) {
        $isText = $ln['kind'] === 'text'; if (!$isText) $i++;
        $zone = $ln['zone'] === 'overseas' ? ' (' . $T('ob.z_overseas') . ')' : '';
        $v = $isText ? ['', '', $ln['description'], '', '', '', '', ''] : [(string)$i, (string)$ln['erp_code'], $ln['description'] . $zone . ($ln['notes'] ? ' — ' . $ln['notes'] : ''), (string)$ln['unit'], rtrim(rtrim(number_format((float)$ln['qty'], 2, '.', ''), '0'), '.'), number_format((float)$ln['unit_price'], 2, ',', '.'), (float)$ln['discount_pct'] > 0 ? rtrim(rtrim(number_format((float)$ln['discount_pct'], 2, '.', ''), '0'), '.') . ' %' : '', number_format((float)$ln['line_total'], 2, ',', '.')];
        $pdf->setFont($isText ? 'B' : 'R', 7.6); $lines = []; $nl = 1; foreach ($cols as $ci => [$lab, $cw, $al]) { $lines[$ci] = $pdf->wrap($v[$ci], $cw - 3); $nl = max($nl, count($lines[$ci])); }
        $hh = $nl * 3.8 + 1.6; if ($y + $hh > 276) { $footer(); $header(); $hrow(); $pdf->setFont($isText ? 'B' : 'R', 7.6); }
        $x = $L; foreach ($cols as $ci => [$lab, $cw, $al]) { $pdf->setColor($line); $pdf->setLineWidth(0.25); $pdf->rect($x, $y, $cw, $hh); $pdf->setColor($ink); foreach ($lines[$ci] as $k => $s) $pdf->text($x + 1.5, $y + 3.5 + 3.8 * $k, $s, $al, $cw - 3); $x += $cw; }
        $y += $hh;
    }
    if (!$o['lines']) { $pdf->setFont('R', 7.6); $pdf->setColor($line); $pdf->rect($L, $y, $W, 6); $pdf->setColor($ink); $pdf->text($L + 1.5, $y + 4, $T('ob.no_lines')); $y += 6; }
    // totals
    $tot = [[$T('ob.net'), ob_money((float)$o['amount'], $cur), true]];
    if ((float)$o['vat_pct'] > 0) { $tot[] = [$T('ob.vat', ['p' => rtrim(rtrim(number_format((float)$o['vat_pct'], 2, '.', ''), '0'), '.')]), ob_money((float)$o['vat_total'], $cur), false]; $tot[] = [$T('ob.gross'), ob_money((float)$o['gross_total'], $cur), true]; }
    else $tot[] = [$T('ob.vat_excl'), '', false];
    $need(count($tot) * 6 + 4); $y += 1;
    foreach ($tot as [$k, $v, $b]) { $pdf->setFont($b ? 'B' : 'R', 8.5); $pdf->setColor($b ? $navy : $ink); $pdf->text($R - 100, $y + 4, $k, 'R', 60); $pdf->text($R - 40, $y + 4, $v, 'R', 38.5); $y += 5.5; }
    $y += 2;
    foreach ($after as $k) $block($k);
    $footer();
    return $pdf->bytes($o['offer_no'] . ' ' . $o['revision']);
}
function ob_render_docx(array $o): string {
    require_once __DIR__ . '/docx.php';
    $o = ob_doc_data($o); $cur = (string)$o['currency']; $loc = ob_locale($o); $T = fn(string $k, array $v = []) => t_in($k, $loc, $v);
    $d = new DocxWriter();
    $bd = function_exists('br_doc') ? br_doc((int)$o['project_id']) : ['logo' => null, 'name' => 'Golden Automation Systems'];
    if (!empty($bd['logo']) && is_file($bd['logo'])) $d->image((string) file_get_contents($bd['logo']), 4.5, 1.6, 'right');
    $d->heading($T('ob.doc_title') . ' — ' . $o['offer_no'] . ' ' . $o['revision'], 1);
    $d->kv($T('of.title_f'), (string)$o['title']); $d->kv($T('rp.customer'), (string)($o['customer_name'] ?? '')); $d->kv($T('v.one'), (string)($o['vessel'] ?: '—')); $d->kv($T('pr.one'), $o['vars']['{project}'] ?: '—');
    $d->kv($T('th.date'), $o['vars']['{date}']); $d->kv($T('of.valid_until'), $o['vars']['{valid_until}']); $d->kv($T('ob.prepared_by'), $o['vars']['{user}'] . ' · ' . $o['vars']['{branch}']);
    if (!empty($o['ticket_no'])) $d->kv($T('tk.one'), (string)$o['ticket_no']);
    $n = 0; $block = function (string $k) use ($o, &$n, $d) { foreach ($o['blocks'] as $b) if ($b['block_key'] === $k && trim($b['body']) !== '') { $n++; $d->heading($n . '. ' . $b['title'], 2); foreach (preg_split('/\n{2,}/', trim($b['body'])) as $p) if (trim($p) !== '') $d->para(trim($p)); } };
    foreach (['intro', 'scope'] as $k) $block($k);
    $n++; $d->heading($n . '. ' . $T('ob.sec_lines'), 2);
    $rows = []; $i = 0;
    foreach ($o['lines'] as $ln) { $isText = $ln['kind'] === 'text'; if (!$isText) $i++; $rows[] = $isText ? ['', '', $ln['description'], '', '', '', '', ''] : [(string)$i, (string)$ln['erp_code'], $ln['description'] . ($ln['zone'] === 'overseas' ? ' (' . $T('ob.z_overseas') . ')' : '') . ($ln['notes'] ? ' — ' . $ln['notes'] : ''), (string)$ln['unit'], rtrim(rtrim(number_format((float)$ln['qty'], 2, '.', ''), '0'), '.'), number_format((float)$ln['unit_price'], 2, ',', '.'), (float)$ln['discount_pct'] > 0 ? (string)(float)$ln['discount_pct'] . ' %' : '', number_format((float)$ln['line_total'], 2, ',', '.')]; }
    $rows[] = ['', '', $T('ob.net'), '', '', '', '', number_format((float)$o['amount'], 2, ',', '.')];
    if ((float)$o['vat_pct'] > 0) { $rows[] = ['', '', $T('ob.vat', ['p' => (string)(float)$o['vat_pct']]), '', '', '', '', number_format((float)$o['vat_total'], 2, ',', '.')]; $rows[] = ['', '', $T('ob.gross'), '', '', '', '', number_format((float)$o['gross_total'], 2, ',', '.')]; }
    else $rows[] = ['', '', $T('ob.vat_excl'), '', '', '', '', ''];
    $d->table([$T('ob.c_no'), $T('ob.c_code'), $T('ob.c_desc'), $T('ob.c_unit'), $T('ob.c_qty'), $T('ob.c_price') . ' (' . $cur . ')', $T('ob.c_disc'), $T('ob.c_total') . ' (' . $cur . ')'], $rows);
    foreach (['exclusions', 'validity', 'payment', 'terms', 'closing'] as $k) $block($k);
    return $d->bytes($o['offer_no'] . ' ' . $o['revision'], (string)($bd['footer'] ?? $bd['name'] ?? ''));
}

/** Issue: archive PDF + Word as the next revision of the offer number, set the PDF as the offer document, draft → sent. */
function ob_issue(int $id): array {
    if (!ob_can()) throw new RuntimeException(t('err.noaccess'));
    if (!function_exists('ar_has') || !ar_has()) throw new RuntimeException(t('ar.need_r20'));
    $o = of_load($id); if (!$o) throw new RuntimeException(t('err.notfound'));
    $wasDraft = $o['status'] === 'draft';
    if ($wasDraft) { $o['status'] = 'sent'; $o['sent_at'] = $o['sent_at'] ?: date('Y-m-d'); }
    $nIss = (int) scalar('SELECT COUNT(DISTINCT revision) FROM sp_files WHERE kind = ? AND doc_no = ? AND project_id = ?', ['issued', $o['offer_no'], (int)$o['project_id']]);
    $o['revision'] = 'R' . $nIss;
    if (!$o['valid_until']) $o['valid_until'] = date('Y-m-d', strtotime($o['sent_at'] . ' +' . (int)$o['validity_days'] . ' days'));
    $pdf = ob_render_pdf($o); $docx = ob_render_docx($o);
    $r = ar_issue($o['offer_no'], (int)$o['project_id'], $o['subproject_id'] ? (int)$o['subproject_id'] : null, [[$pdf, 'pdf', 'application/pdf'], [$docx, 'docx', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document']], 'external', $o['offer_no'] . ' ' . $o['title']);
    $pdfId = (int)($r['ids'][0] ?? 0);
    q('UPDATE offers SET revision = ?, file_id = ?, status = ?, sent_at = ?, status_at = ?, valid_until = ? WHERE id = ?', [$r['revision'], $pdfId ?: $o['file_id'], $o['status'], $o['sent_at'], $wasDraft ? $o['sent_at'] : $o['status_at'], $o['valid_until'], $id]);
    of_event($id, $wasDraft ? 'sent' : 'edited', t('ob.ev_issued', ['r' => $r['revision']]) . ($wasDraft ? ' · ' . of_money((float)$o['amount'], $o['currency']) : ''));
    return $r;
}

/** Offers linked to a ticket / vessel (for their pages). */
function ob_for_ticket(int $ticketId): array { return ob_has() ? of_list(['ticket' => $ticketId]) : []; }
function ob_for_vessel(int $vesselId): array { return of_has() ? of_list(['vessel' => $vesselId]) : []; }
